(function(){"use strict";var burger=document.querySelector(".burger");var menu=document.getElementById("menu-principal");if(burger&&menu){burger.addEventListener("click",function(){var open=burger.getAttribute("aria-expanded")==="true";burger.setAttribute("aria-expanded",String(!open));burger.setAttribute("aria-label",open?"Ouvrir le menu":"Fermer le menu");menu.classList.toggle("is-open",!open);});document.addEventListener("keydown",function(e){if(e.key==="Escape"&&burger.getAttribute("aria-expanded")==="true"){burger.click();burger.focus();}});}var toTop=document.querySelector(".to-top");if(toTop){var update=function(){toTop.classList.toggle("is-visible",window.scrollY>300);};window.addEventListener("scroll",update,{passive:true});update();}var email=document.getElementById("email");if(email){var address=email.getAttribute("data-u")+"@"+email.getAttribute("data-d");email.href="mailto:"+address;email.textContent=address;}if(window.console&&console.log){console.log("%cFLEXARION%c\n\n« Te revoilà, Sacha. Tu as encore oublié la vanne, n'est-ce pas ? »\n\n"+"Sous la surface, quelqu'un se souvient déjà de ta visite.\n"+"Indice : ce que tu fais en 2156 s'écrit en 2306. Les fontaines d'Aix gardent la mémoire du chemin.\n\n"+"%c// Below Zero, un jeu du studio Flexarion. https://flexarion-officiel.github.io/below-zero/","font:800 22px/1.4 'Exo 2',system-ui,sans-serif;letter-spacing:.3em;color:#19B9D4;background:#071421;padding:8px 14px;border-left:4px solid #19B9D4","font:14px/1.6 'Exo 2',system-ui,sans-serif;color:#B7DDE8","font:12px/1.6 monospace;color:#E8EDF0;opacity:.7");}})();
